  function coreMarkup(prefix){return `<div class="mr-core-wrap" data-core="${prefix}"><svg class="mr-core-svg" viewBox="0 0 300 300" aria-label="Resilience Core"><g class="mr-core-grid"><circle cx="150" cy="150" r="112"/><circle cx="150" cy="150" r="84"/><circle cx="150" cy="150" r="56"/></g><g class="mr-core-axes"></g><polygon class="mr-core-field-shadow" points=""/><polygon class="mr-core-field" points=""/><g class="mr-pressure-lines"></g></svg><div class="mr-core-center"><div><b data-core-score>—</b><small data-i18n="score">${t('score')}</small></div></div><span class="mr-core-badge ${state.demo?'':'live'}" data-core-badge>${state.demo?t('sample'):t('live')}</span></div>`}
  function dockButton(tool,ic,label,active){return `<button type="button" data-tool="${tool}" class="${active?'active':''}">${ic}<span data-i18n="${label}">${t(label)}</span></button>`}
