  qsa('[data-core]').forEach(core=>{const axes=qs('.mr-core-axes',core),pressure=qs('.mr-pressure-lines',core),names=['cash','fx','inflation','rate','crypto','currency'];names.forEach((name,i)=>{const a=(-90+i*60)*Math.PI/180,x=150+112*Math.cos(a),y=150+112*Math.sin(a);axes.insertAdjacentHTML('beforeend',`<line class="mr-core-axis" x1="150" y1="150" x2="${x}" y2="${y}"/>`);pressure.insertAdjacentHTML('beforeend',`<line class="mr-pressure ${name}" data-pressure="${name}" x1="${150+74*Math.cos(a)}" y1="${150+74*Math.sin(a)}" x2="${150+112*Math.cos(a)}" y2="${150+112*Math.sin(a)}"/>`)})});
  let oldPoints={};function polygonPoints(r){const f=[r.pressures.cash,r.pressures.fx,r.pressures.inflation,r.pressures.rate,r.pressures.crypto,r.pressures.currency],arr=[],N=18;for(let i=0;i<N;i++){const angle=-Math.PI/2+i*(Math.PI*2/N),sector=i/(N/6),idx=Math.floor(sector)%6,frac=sector-Math.floor(sector),next=(idx+1)%6,local=f[idx]*(1-frac)+f[next]*frac,radius=108-local*38+Math.sin(i*1.7)*2;arr.push([150+Math.cos(angle)*radius,150+Math.sin(angle)*radius])}return arr}function ptsString(pts){return pts.map(p=>p[0].toFixed(1)+','+p[1].toFixed(1)).join(' ')}function morph(poly,key,next){const prev=oldPoints[key]||next;oldPoints[key]=next.map(p=>p.slice());if(reduceMotion){poly.setAttribute('points',ptsString(next));return}const start=performance.now(),dur=380;function frame(now){const x=clamp((now-start)/dur,0,1),e=1-Math.pow(1-x,3),pts=next.map((p,i)=>[prev[i][0]+(p[0]-prev[i][0])*e,prev[i][1]+(p[1]-prev[i][1])*e]);poly.setAttribute('points',ptsString(pts));if(x<1)requestAnimationFrame(frame)}requestAnimationFrame(frame)}
