  function updateFactors(r){const labels={cash:'Cash',fx:'FX',inflation:'CPI',rate:'Rate',crypto:'Crypto',currency:'Mix'};qs('#mrFactorLegend').innerHTML=Object.keys(labels).map(k=>`<div class="mr-factor"><i style="--o:${(.25+r.pressures[k]*.75).toFixed(2)}"></i><span>${labels[k]}</span><b>${Math.round(r.pressures[k]*100)}</b></div>`).join('')}function updateFlow(r){qs('#mrExposureFlow').textContent=`${biggestLabel(r)} ${yen(r.exposure[1])}`;qs('#mrScoreFlow').textContent=`${t('score')} ${r.score}`}
