  function updateAssumptions(){const s=scenarios[state.scenario],v={fx:'+'+Math.round(s.fx*100)+'%',inflation:'+'+Math.round(s.inflation*100)+'%',rate:'+'+one.format(s.rate*100)+'pt',crypto:'-'+Math.round(s.crypto*100)+'%'};Object.entries(v).forEach(([k,x])=>qsa(`[data-assume="${k}"]`).forEach(el=>el.textContent=x));qs('#mrStressLabel').textContent=s.label[state.lang]}function updateLanguage(){qsa('[data-i18n]').forEach(el=>{const k=el.dataset.i18n;if(copy[state.lang][k])el.textContent=t(k)});qsa('[data-lang]').forEach(b=>b.classList.toggle('active',b.dataset.lang===state.lang));document.documentElement.lang=state.lang;qs('#mrStressLabel').textContent=scenarios[state.scenario].label[state.lang]}
  function highlightFactor(key){const map={income:'cash',essential:'inflation',cash:'cash',fxSpend:'fx',variableDebt:'rate',crypto:'crypto',currencyShare:'currency'},factor=map[key]||key;qsa('.mr-control').forEach(c=>c.classList.toggle('active-factor',c.dataset.factor===key));qsa(`[data-pressure="${factor}"]`).forEach(line=>{if(!reduceMotion)line.animate([{filter:'drop-shadow(0 0 0 rgba(124,231,194,0))'},{filter:'drop-shadow(0 0 8px rgba(124,231,194,.75))'},{filter:'drop-shadow(0 0 0 rgba(124,231,194,0))'}],{duration:520,easing:'ease-out'})})}function renderAll(changed){const r=compute();updateCore(r);updateAssumptions();updateResults(r);updateFactors(r);updateTools(r);updateFlow(r);updateLanguage();if(changed)highlightFactor(changed)}
  function switchTool(tool){if(tool==='market'){qs('#mrPreview').scrollIntoView({behavior:reduceMotion?'auto':'smooth',block:'center'});closeLayers();return}const next=qs(`[data-tool-panel="${tool}"]`),old=qs('.mr-tool-panel.active');if(!next||next===old)return;old&&old.classList.remove('active');next.classList.add('active');state.tool=tool;qsa('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===tool));qsa('[data-mobile]').forEach(b=>b.classList.toggle('active',b.dataset.mobile===tool));if(!reduceMotion)next.animate([{opacity:0,transform:'translateX(18px)'},{opacity:1,transform:'translateX(0)'}],{duration:300,easing:'cubic-bezier(.2,.78,.24,1)'});capture('money_resilience_tool_switch',{tool});closeLayers();qs('#mrWorkspace').scrollIntoView({behavior:reduceMotion?'auto':'smooth',block:'start'})}
  function layer(sel,open){const overlay=qs('#mrOverlay'),el=qs(sel);if(!el)return;if(open){overlay.classList.add('open');el.classList.add('open');document.body.style.overflow='hidden'}else{el.classList.remove('open');if(!qs('.mr-drawer.open')&&!qs('.mr-sheet.open')){overlay.classList.remove('open');document.body.style.overflow=''}}}function closeLayers(){qsa('.mr-drawer.open,.mr-sheet.open').forEach(el=>el.classList.remove('open'));qs('#mrOverlay').classList.remove('open');document.body.style.overflow=''}function toast(msg){const el=qs('#mrToast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),1600)}

  qsa('[data-value]').forEach(input=>{const key=input.dataset.value;input.addEventListener('focus',()=>highlightFactor(key));input.addEventListener('input',()=>syncValue(key,parse(input.value)));input.addEventListener('blur',()=>formatInput(key))});qsa('[data-range]').forEach(r=>{const key=r.dataset.range;formatInput(key);r.addEventListener('input',()=>syncValue(key,Number(r.value)))});qsa('[data-mini]').forEach(input=>input.addEventListener('input',()=>{state[input.dataset.mini]=parse(input.value);renderAll()}));qs('#mrScenario').addEventListener('input',e=>{const next=Number(e.target.value);if(next===state.scenario)return;state.scenario=next;markPersonal();renderAll('scenario');capture('money_resilience_scenario_change',{scenario:scenarios[next].key});if(!reduceMotion)qsa('.mr-assume b').forEach((el,i)=>el.animate([{transform:'translateY(4px)',opacity:.35},{transform:'translateY(0)',opacity:1}],{duration:260,delay:i*28,easing:'cubic-bezier(.2,.78,.24,1)'}))});qs('#mrUseMine').addEventListener('click',()=>{state.demo=false;['income','essential','cash'].forEach(k=>{state[k]=0;formatInput(k)});renderAll();qsa('[data-value="income"]')[0].focus();capture('money_resilience_start',{source:'hero_cta'})});qsa('[data-tool]').forEach(b=>b.addEventListener('click',()=>switchTool(b.dataset.tool)));qsa('[data-nav]').forEach(b=>b.addEventListener('click',()=>switchTool(b.dataset.nav)));qsa('[data-mobile]').forEach(b=>b.addEventListener('click',()=>switchTool(b.dataset.mobile)));qsa('[data-open-drawer]').forEach(b=>b.addEventListener('click',()=>layer('#mrDrawer',true)));qsa('[data-open-advanced]').forEach(b=>b.addEventListener('click',()=>layer('#mrAdvanced',true)));qsa('[data-close-layer]').forEach(b=>b.addEventListener('click',closeLayers));qs('#mrOverlay').addEventListener('click',closeLayers);bindOpenInfo();qsa('[data-lang]').forEach(b=>b.addEventListener('click',()=>{state.lang=b.dataset.lang;renderAll();capture('money_resilience_language_change',{language:state.lang})}));document.addEventListener('keydown',e=>{if(e.key==='Escape')closeLayers()});qs('#mrCopy').addEventListener('click',async()=>{const r=compute(),text=`Money Resilience ${r.score}/100\n${t('shock')}: ${yen(r.monthlyImpact)}\n${t('runway')}: ${one.format(r.bufferMonths)} months\n${t('exposure')}: ${biggestLabel(r)} ${yen(r.exposure[1])}\n${location.href}`;try{await navigator.clipboard.writeText(text);toast(state.lang==='ja'?'コピーしました':'Copied');capture('money_resilience_result_copy',{score_band:r.score>=80?'80_100':r.score>=60?'60_79':r.score>=40?'40_59':'0_39',scenario:r.scenario.key})}catch(_){toast('Copy failed')}});qs('#mrPrint').addEventListener('click',()=>{capture('money_resilience_result_print',{scenario:scenarios[state.scenario].key});window.print()});qs('#mrReset').addEventListener('click',()=>{Object.assign(state,{demo:false,income:0,essential:0,cash:0,fxSpend:0,variableDebt:0,crypto:0,currencyShare:0,scenario:1});['income','essential','cash','fxSpend','variableDebt','crypto','currencyShare'].forEach(formatInput);qs('#mrScenario').value=1;renderAll();capture('money_resilience_reset')});

  const API='https://api.frankfurter.dev/v2/rates',CACHE='mr_market_pulse_ecb_vnext';function reciprocal(n){return n>0?1/n:0}function dateAgo(days){const d=new Date();d.setDate(d.getDate()-days);return d.toISOString().slice(0,10)}function marketPath(values,w=126,h=76,pad=5){if(values.length<2)return'';const min=Math.min(...values),max=Math.max(...values),range=max-min||1;return values.map((v,i)=>{const x=pad+i/(values.length-1)*(w-pad*2),y=h-pad-(v-min)/range*(h-pad*2);return`${i?'L':'M'}${x.toFixed(1)},${y.toFixed(1)}`}).join(' ')}function renderMarket(payload){const rates=Object.fromEntries(payload.latest.map(x=>[x.quote,reciprocal(x.rate)])),hist=payload.history.map(x=>({date:x.date,value:reciprocal(x.rate)})).filter(x=>x.value>0).sort((a,b)=>a.date.localeCompare(b.date));if(!rates.USD||!rates.EUR||!rates.GBP||hist.length<2)return;const vals=hist.map(x=>x.value),delta=(vals[vals.length-1]-vals[0])/vals[0]*100;Object.assign(state.market,{usd:rates.USD,eur:rates.EUR,gbp:rates.GBP,delta,low:Math.min(...vals),high:Math.max(...vals),date:(payload.latest[0]&&payload.latest[0].date)||hist[hist.length-1].date,history:vals});qs('#mrUsd').textContent=fxFmt.format(rates.USD);qs('#mrEur').textContent=fxFmt.format(rates.EUR);qs('#mrGbp').textContent=fxFmt.format(rates.GBP);qs('#mrMarketDate').textContent=state.market.date;const d=qs('#mrMarketDelta');d.textContent=`30D ${delta>=0?'+':''}${delta.toFixed(2)}%`;d.classList.toggle('down',delta<0);const line=qs('#mrLine'),spark=qs('#mrSpark');line.setAttribute('d',marketPath(vals));spark.classList.remove('draw');if(!reduceMotion)requestAnimationFrame(()=>spark.classList.add('draw'))}async function loadMarket(){try{let cached=null;try{cached=JSON.parse(sessionStorage.getItem(CACHE)||'null')}catch(_){}if(cached&&Date.now()-cached.t<300000){renderMarket(cached.p);return}const from=dateAgo(38),res=await Promise.all([fetch(`${API}?base=JPY&quotes=USD,EUR,GBP&providers=ECB`,{cache:'no-store'}),fetch(`${API}?base=JPY&quotes=USD&from=${from}&providers=ECB`,{cache:'no-store'})]);if(!res[0].ok||!res[1].ok)throw new Error('market');const p={latest:await res[0].json(),history:await res[1].json()};try{sessionStorage.setItem(CACHE,JSON.stringify({t:Date.now(),p}))}catch(_){}renderMarket(p);capture('money_resilience_market_pulse_loaded',{provider:'ECB_via_Frankfurter'})}catch(_){qs('#mrMarketDate').textContent=state.lang==='ja'?'取得待ち':'Waiting';capture('money_resilience_market_pulse_error',{provider:'ECB_via_Frankfurter'})}}
  renderAll();loadMarket();setInterval(()=>{if(document.visibilityState==='visible')loadMarket()},300000);capture('money_resilience_vnext_loaded',{ui_version:'vnext_motion_product'});
